// Data-driven routes: every service answers exactly what the pack lists for the test customer (status, body, delay).
// `data.json` is generated by build_data.py from the pack's test-customer file; the service table there gives the
// contract path and the request fields that select the answer.
import data from "./data.json";

const sleep = (s) => new Promise((r) => setTimeout(r, s * 1000));

function failure(code, text) {
  return { result: { guid: "mock-" + Date.now().toString(16), returnCode: code, messageText: text, code, message: text, type: null,
                     details: { guid: "mock", rootCause: null, errorOrigin: null } } };
}

// A field may come in body.data (the contract), at the body's top level, or as a query parameter.
function field(body, query, name) {
  const d = body && typeof body.data === "object" && body.data ? body.data : null;
  let v = d && d[name] !== undefined ? d[name] : body && body[name] !== undefined ? body[name] : query.get(name);
  if (v === null || v === undefined) return "";
  v = String(v).trim();
  if (v.startsWith("{{") || v.startsWith("%7B%7B")) return "{{template}}";     // the panel's test button sends variables unfilled
  return v;
}

const digits = (s) => String(s).replace(/\D/g, "");

export const routes = Object.entries(data.services).map(([name, svc]) => ({
  method: svc.method,
  paths: [svc.path, "/" + name, "/" + name.replace(/\./g, "/")],
  async handle({ query, body, json }) {
    let no = field(body, query, svc.keys[0]);
    if (no === "{{template}}") no = Object.keys(data.customers)[0];
    const customer = data.customers[no];
    if (!customer) return json(failure("FB_IVR_CHANNEL_101", "Müşteri bulunamadı."), 404);
    const table = customer.services[name];
    if (!table) return json(failure("FB_IVR_CHANNEL_102", "Müşteriye ait kayıt bulunamadı."), 404);
    const want = svc.keys.slice(1).map((k) => field(body, query, k));
    let answer = table[want.join("|")];
    if (!answer) {
      // tolerate a card given unmasked or by its last digits, a week given as "2. hafta", and unfilled template values
      for (const [k, a] of Object.entries(table)) {
        const parts = k.split("|");
        const ok = parts.every((p, i) => {
          const w = want[i];
          if (w === "{{template}}" || p === w) return true;
          if (i === 0) { const wd = digits(w); return wd.length >= 4 && (digits(p).endsWith(wd) || (wd.length >= 10 && wd.slice(0, 6) === digits(p).slice(0, 6) && wd.slice(-4) === digits(p).slice(-4))); }
          return digits(w) !== "" && digits(w) === digits(p);
        });
        if (ok) { answer = a; break; }
      }
    }
    if (!answer) return json(failure("FB_IVR_CHANNEL_103", "Kayıt bulunamadı."), 404);
    if (answer.delay) await sleep(Math.min(answer.delay, 25));
    return json(answer.body, answer.http);
  },
}));
